INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (401, 102301, "2020/07/31 12:00:00", 2, 0.0, 10046, 0.0, 0.0, 24001, 24, "2030/12/17 14:59:59", "アヤネ", 2, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (402, 102301, "2020/07/31 12:00:00", 2, 0.0, 10046, 2.21, 0.0, 24002, 24, "2030/12/17 14:59:59", "アヤネ", 1, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (403, 102301, "2020/07/31 12:00:00", 2, 0.0, 10046, 0.0, 0.0, 24003, 24, "2030/12/17 14:59:59", "アヤネ", 2, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (701, 192201, "2020/07/31 12:00:00", 1, 0.0, 10046, 1.99, 0.0, 24004, 24, "2030/12/17 14:59:59", "アサヒ", 2, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (702, 192201, "2020/07/31 12:00:00", 2, 0.0, 10046, 2.21, 0.0, 24005, 24, "2030/12/17 14:59:59", "アサヒ", 1, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (703, 192201, "2020/07/31 12:00:00", 1, 0.0, 10046, 3.33, 0.0, 24006, 24, "2030/12/17 14:59:59", "アサヒ", 2, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (801, 192301, "2020/07/31 12:00:00", 2, 0.0, 10046, 0.0, 0.0, 24007, 24, "2030/12/17 14:59:59", "部員３", 2, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (802, 192301, "2020/07/31 12:00:00", 2, 0.0, 10046, 2.68, 0.0, 24008, 24, "2030/12/17 14:59:59", "部員３", 1, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (803, 192301, "2020/07/31 12:00:00", 2, 0.0, 10046, 0.0, 0.0, 24009, 24, "2030/12/17 14:59:59", "部員３", 2, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (501, 192501, "2020/07/31 12:00:00", 1, 0.0, 10046, 0.0, 0.0, 24010, 24, "2030/12/17 14:59:59", "", 1, "やった！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (502, 192501, "2020/07/31 12:00:00", 1, 0.0, 10046, 0.0, 0.0, 24011, 24, "2030/12/17 14:59:59", "", 1, "勝ったよ！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (503, 192501, "2020/07/31 12:00:00", 1, 0.0, 10046, 0.0, 0.0, 24012, 24, "2030/12/17 14:59:59", "", 1, "いい調子！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (111, 113501, "2020/07/31 12:00:00", 2, 0.0, 10046, 5.33, 0.0, 24013, 24, "2030/12/17 14:59:59", "ミサト", 6, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (112, 113501, "2020/07/31 12:00:00", 2, 0.0, 10046, 6.85, 0.0, 24014, 24, "2030/12/17 14:59:59", "ミサト", 1, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (113, 113501, "2020/07/31 12:00:00", 2, 0.0, 10046, 3.0, 0.0, 24015, 24, "2030/12/17 14:59:59", "ミサト", 1, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (611, 192401, "2020/07/31 12:00:00", 2, 0.0, 10046, 6.11, 0.0, 24016, 24, "2030/12/17 14:59:59", "ダイチ", 1, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (612, 192401, "2020/07/31 12:00:00", 2, 0.0, 10046, 6.75, 0.0, 24017, 24, "2030/12/17 14:59:59", "ダイチ", 1, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (613, 192401, "2020/07/31 12:00:00", 2, 0.0, 10046, 0.0, 0.0, 24018, 24, "2030/12/17 14:59:59", "ダイチ", 2, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (211, 113401, "2020/07/31 12:00:00", 1, 0.0, 10046, 4.52, 0.0, 24019, 24, "2030/12/17 14:59:59", "ハツネ", 2, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (212, 113401, "2020/07/31 12:00:00", 1, 0.0, 10046, 3.89, 0.0, 24020, 24, "2030/12/17 14:59:59", "ハツネ", 2, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (213, 113401, "2020/07/31 12:00:00", 2, 0.0, 10046, 13.49, 0.0, 24021, 24, "2030/12/17 14:59:59", "ハツネ", 1, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (311, 106501, "2020/07/31 12:00:00", 2, 0.0, 10046, 3.17, 0.0, 24022, 24, "2030/12/17 14:59:59", "カヤ", 1, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (312, 106501, "2020/07/31 12:00:00", 2, 0.0, 10046, 4.42, 0.0, 24023, 24, "2030/12/17 14:59:59", "カヤ", 1, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (313, 106501, "2020/07/31 12:00:00", 1, 0.0, 10046, 2.89, 0.0, 24024, 24, "2030/12/17 14:59:59", "カヤ", 6, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (421, 102301, "2020/07/31 12:00:00", 3, 0.0, 10046, 3.71, 0.0, 24025, 24, "2030/12/17 14:59:59", "アヤネ", 4, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (721, 192201, "2020/07/31 12:00:00", 1, 0.0, 10046, 5.1, 0.0, 24026, 24, "2030/12/17 14:59:59", "アサヒ", 2, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (821, 192301, "2020/07/31 12:00:00", 3, 0.0, 10046, 4.34, 0.0, 24027, 24, "2030/12/17 14:59:59", "部員３", 1, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (521, 192501, "2020/07/31 12:00:00", 1, 0.0, 10046, 0.0, 0.0, 24028, 24, "2030/12/17 14:59:59", "", 1, "いい勝負だったよ\nまたやろうね");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (101, 113501, "2020/07/31 12:00:00", 2, -360.0, 10046, 5.62, 0.0, 24029, 24, "2030/12/17 14:59:59", "ミサト", 1, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (102, 113501, "2020/07/31 12:00:00", 2, -360.0, 10046, 9.58, 0.0, 24030, 24, "2030/12/17 14:59:59", "ミサト", 1, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (103, 113501, "2020/07/31 12:00:00", 2, -360.0, 10046, 0.0, 0.0, 24031, 24, "2030/12/17 14:59:59", "ミサト", 2, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (104, 113501, "2020/07/31 12:00:00", 1, -360.0, 10046, 9.13, 0.0, 24032, 24, "2030/12/17 14:59:59", "ミサト", 2, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (105, 113501, "2020/07/31 12:00:00", 2, -360.0, 10046, 8.27, 0.0, 24033, 24, "2030/12/17 14:59:59", "ミサト", 1, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！");
